class AVLNode:
    __slots__ = ('val', 'left', 'right', 'h')
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None
        self.h = 1

class AVL:
    def __init__(self):
        self.root = None

    @staticmethod
    def _h(n):
        return n.h if n else 0

    def _pull(self, n):
        n.h = 1 + max(self._h(n.left), self._h(n.right))

    def _bf(self, n):
        return self._h(n.right) - self._h(n.left)

    def _rr(self, a):
        b = a.right
        a.right = b.left
        b.left = a
        self._pull(a)
        self._pull(b)
        return b

    def _rl(self, a):
        b = a.left
        a.left = b.right
        b.right = a
        self._pull(a)
        self._pull(b)
        return b

    def _balance(self, n):
        bf = self._bf(n)
        if bf > 1:
            if self._bf(n.right) >= 0:      # RR
                return self._rr(n)
            n.right = self._rl(n.right)     # RL
            return self._rr(n)
        if bf < -1:
            if self._bf(n.left) <= 0:       # LL
                return self._rl(n)
            n.left = self._rr(n.left)       # LR
            return self._rl(n)
        return n

    def _insert(self, n, val):
        if n is None:
            return AVLNode(val)
        if val < n.val:
            n.left = self._insert(n.left, val)
        else:
            n.right = self._insert(n.right, val)
        self._pull(n)
        return self._balance(n)

    def insert(self, val):
        self.root = self._insert(self.root, val)

    def _min(self, n):
        while n.left:
            n = n.left
        return n

    def _delete(self, n, val):
        if n is None:
            return None
        if val < n.val:
            n.left = self._delete(n.left, val)
        elif val > n.val:
            n.right = self._delete(n.right, val)
        else:
            if n.left is None:
                return n.right
            if n.right is None:
                return n.left
            m = self._min(n.right)          # 后继替换
            n.val = m.val
            n.right = self._delete(n.right, m.val)
        self._pull(n)
        return self._balance(n)

    def delete(self, val):
        self.root = self._delete(self.root, val)

    def search(self, val):
        n = self.root
        while n and n.val != val:
            n = n.left if val < n.val else n.right
        return n is not None

    def inorder(self):
        out = []
        def dfs(n):
            if n is None:
                return
            dfs(n.left)
            out.append(n.val)
            dfs(n.right)
        dfs(self.root)
        return out

    def height(self):
        return self._h(self.root)


def _is_avl(n):
    if n is None:
        return True, 0
    ok_l, hl = _is_avl(n.left)
    ok_r, hr = _is_avl(n.right)
    ok = ok_l and ok_r and abs(hl - hr) <= 1
    return ok, 1 + max(hl, hr)


def _is_bst(n, lo=-float('inf'), hi=float('inf')):
    if n is None:
        return True
    if not (lo < n.val <= hi):
        return False
    return _is_bst(n.left, lo, n.val) and _is_bst(n.right, n.val, hi)


if __name__ == "__main__":
    import random
    random.seed(9)
    t = AVL()
    arr = []
    for _ in range(3000):
        v = random.randint(0, 100000)
        t.insert(v)
        arr.append(v)
    assert t.inorder() == sorted(arr)
    ok, _ = _is_avl(t.root)
    assert ok, "AVL balance broken"
    # 树高上界验证：1.44*log2(n+2)
    import math
    n = len(arr)
    bound = 1.44 * math.log2(n + 2) + 1
    assert t.height() <= bound, (t.height(), bound)
    # 有序插入也不退化
    t2 = AVL()
    for i in range(2000):
        t2.insert(i)
    ok, _ = _is_avl(t2.root)
    assert ok and t2.height() < 30
    # 删除一半
    uniq = sorted(set(arr))
    removed = set(uniq[:len(uniq) // 2])
    for v in removed:
        while t.search(v):
            t.delete(v)
    expect = sorted(a for a in arr if a not in removed)
    assert t.inorder() == expect
    ok, _ = _is_avl(t.root)
    assert ok, "AVL broken after deletes"
    assert t.inorder() == sorted(t.inorder())
    print("All tests passed.")
